const http=require('http');const crypto=require('crypto');const {URL}=require('url');
const publicPort=Number(process.env.PORT||10000);const internalPort=publicPort+1;process.env.PORT=String(internalPort);require('./server.js');
const RESOURCES=new Set(['manifest.json','catalog','meta','stream']);const PUBLIC=new Set(['configure','health','xtream-health','artwork','qr']);const SECRET=process.env.XSPORTSX_CONFIG_SECRET||'change-this-xsportsx-secret-in-render';const KEY=crypto.createHash('sha256').update(SECRET).digest();const BUILD_VERSION='8.5.0';
const LEAGUES={nfl:['NFL','🏈'],ncaaf:['NCAA Football','🏈'],nba:['NBA','🏀'],wnba:['WNBA','🏀'],ncaab:['NCAA Basketball','🏀'],mlb:['MLB','⚾'],nhl:['NHL','🏒'],mls:['MLS','⚽'],epl:['Premier League','⚽'],ucl:['UEFA Champions League','⚽'],laliga:['LaLiga','⚽'],seriea:['Serie A','⚽'],bundesliga:['Bundesliga','⚽'],ligue1:['Ligue 1','⚽'],ufc:['UFC','🥊'],boxing:['Boxing','🥊']};
function decrypt(t){try{const[a,b,c]=String(t||'').split('.');if(!a||!b||!c)return null;const d=crypto.createDecipheriv('aes-256-gcm',KEY,Buffer.from(a,'base64url'));d.setAuthTag(Buffer.from(b,'base64url'));return JSON.parse(Buffer.concat([d.update(Buffer.from(c,'base64url')),d.final()]).toString())}catch{return null}}
function selected(t){const c=decrypt(t);if(!c||!Array.isArray(c.sports))return new Set();return new Set(c.sports.map(String).filter(x=>LEAGUES[x]))}
function tokenFrom(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i>0)return p[i-1];if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json'))return p[0];return u.searchParams.get('config')||''}
function rewrite(raw){const u=new URL(raw||'/','http://local');let p=u.pathname.split('/').filter(Boolean);if(p[0]==='v527')p=p.slice(1);const i=p.findIndex(x=>RESOURCES.has(x)||x.startsWith('catalog')||x.startsWith('meta')||x.startsWith('stream'));if(i<0){if(p.length===1&&!PUBLIC.has(p[0])&&!p[0].endsWith('.json')){u.pathname='/manifest.json';u.searchParams.set('config',p[0])}return u.pathname+(u.search||'')}const before=p.slice(0,i);u.pathname='/'+p.slice(i).join('/');if(before.length)u.searchParams.set('config',before[before.length-1]);return u.pathname+(u.search||'')}
function manifest(base,t){const s=selected(t);const catalogs=[...s].map(id=>({type:'tv',id,name:`${LEAGUES[id][1]} ${LEAGUES[id][0]}`,extra:[],showInHome:true}));return{id:`community.xsportsx.v8.5.${crypto.createHash('sha256').update(String(t)).digest('hex').slice(0,20)}`,version:BUILD_VERSION,name:'XSportsX',description:'XSportsX 8.5 private sports connection.',resources:[{name:'catalog',types:['tv']},{name:'meta',types:['tv']},{name:'stream',types:['tv']}],types:['tv'],idPrefixes:['sport:','xtream:'],catalogs,behaviorHints:{configurable:false,configurationRequired:false},logo:`${base}/artwork/other.svg`}}
function configPage(base){const groups=[['FOOTBALL',['nfl','ncaaf']],['BASKETBALL',['nba','wnba','ncaab']],['BASEBALL & HOCKEY',['mlb','nhl']],['SOCCER',['mls','epl','ucl','laliga','seriea','bundesliga','ligue1']],['COMBAT',['ufc','boxing']]];let html='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>XSportsX 8.5</title><style>body{margin:0;background:#050810;color:#fff;font-family:Arial,sans-serif}main{max-width:900px;margin:auto;padding:20px}.card{background:#0b111c;border:1px solid #24324a;border-radius:18px;padding:20px;margin:14px 0}h1{margin:0 0 8px}.muted{color:#8c9ab0}.league{display:block;margin:8px 0;padding:14px;background:#101a29;border:1px solid #2b3b54;border-radius:12px;font-size:17px}.league input{width:22px;height:22px;vertical-align:middle;margin-right:12px;accent-color:#ff263d}.tools button,.create{padding:13px 16px;margin:4px;border:1px solid #30415b;border-radius:10px;background:#121c2b;color:#fff;font-weight:bold}.create{width:100%;margin:15px 0;background:#ff263d;border:0}.count{font-weight:bold;color:#ff6676;font-size:18px;margin:12px 0}input[type=text],input[type=password]{width:100%;padding:14px;margin:6px 0;box-sizing:border-box;background:#070c14;border:1px solid #30415b;border-radius:10px;color:#fff}</style></head><body><main><div class="card"><h1>XSportsX</h1><div class="muted">BUILD 8.5.0 • SIMPLE LEAGUE SELECTOR</div></div><div class="card"><h2>Source</h2><input id="base" type="text" placeholder="Xtream server URL"><input id="user" type="text" placeholder="Username"><input id="pass" type="password" placeholder="Password"></div><div class="card"><h2>Select leagues</h2><div id="count" class="count">0 selected</div><div class="tools"><button type="button" id="all">Select All</button><button type="button" id="none">Clear All</button></div>';
for(const[g,ids]of groups){html+=`<h3>${g}</h3>`;for(const id of ids){html+=`<label class="league"><input class="leagueBox" type="checkbox" value="${id}">${LEAGUES[id][1]} ${LEAGUES[id][0]}</label>`}}
html+=`</div><div class="card"><button id="create" class="create" type="button" disabled>Create Private Connection</button><div id="result" class="muted"></div></div></main><script>
function boxes(){return Array.from(document.querySelectorAll('.leagueBox'))}function refresh(){const n=boxes().filter(x=>x.checked).length;document.getElementById('count').textContent=n+' selected';document.getElementById('create').disabled=n===0}boxes().forEach(x=>x.addEventListener('change',refresh));document.getElementById('all').onclick=function(){boxes().forEach(x=>x.checked=true);refresh()};document.getElementById('none').onclick=function(){boxes().forEach(x=>x.checked=false);refresh()};document.getElementById('create').onclick=async function(){const sports=boxes().filter(x=>x.checked).map(x=>x.value);const r=document.getElementById('result');r.textContent='Creating…';try{const z=await fetch('${base}/configure',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({source:'xtream',sports,xtream:{baseUrl:document.getElementById('base').value,username:document.getElementById('user').value,password:document.getElementById('pass').value}})});const d=await z.json();if(!z.ok)throw Error(d.error||'Failed');r.innerHTML='<br><b>'+sports.length+' leagues selected</b><br><br><a style="color:#8fc5ff;word-break:break-all" href="'+d.manifestUrl+'">'+d.manifestUrl+'</a>'}catch(e){r.textContent=e.message}};refresh();</script></body></html>`;return html}
const proxy=http.createServer((req,res)=>{try{const token=tokenFrom(req.url),path=rewrite(req.url),parsed=new URL(path,'http://local').pathname,base=`${String(req.headers['x-forwarded-proto']||'https').split(',')[0]}://${req.headers.host||'localhost'}`;if(req.method==='GET'&&parsed==='/configure'){const body=configPage(base);res.writeHead(200,{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION,'content-length':Buffer.byteLength(body)});return res.end(body)}if(req.method==='GET'&&parsed==='/manifest.json'&&token){const s=selected(token);if(!s.size){res.writeHead(400,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION});return res.end(JSON.stringify({error:'No leagues selected'}))}const body=JSON.stringify(manifest(base,token));res.writeHead(200,{'content-type':'application/json','cache-control':'no-store','x-xsportsx-build':BUILD_VERSION,'x-xsportsx-selected-leagues':[...s].join(',')});return res.end(body)}const upstream=http.request({hostname:'127.0.0.1',port:internalPort,path,method:req.method,headers:{...req.headers,host:`127.0.0.1:${internalPort}`}},response=>{res.writeHead(response.statusCode||502,{...response.headers,'x-xsportsx-build':BUILD_VERSION});response.pipe(res)});upstream.on('error',e=>{res.statusCode=502;res.end(e.message)});req.pipe(upstream)}catch(e){res.statusCode=400;res.end(e.message)}});proxy.listen(publicPort,'0.0.0.0',()=>console.log('XSportsX '+BUILD_VERSION));